<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#8CAAEE;">  interval</span><span style="--shiki-light:#179299;--shiki-dark:#81C8BE;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6D189;"> 30s</span></span>
